import React, { useState } from 'react';
import { Search, Filter, SlidersHorizontal } from 'lucide-react';
import { PROJECTS } from '../constants';
import { ProjectStatus, ResearchArea } from '../types';

const Projects: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedArea, setSelectedArea] = useState<string>('All');
  const [selectedStatus, setSelectedStatus] = useState<string>('All');

  const filteredProjects = PROJECTS.filter(project => {
    const matchesSearch = project.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          project.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesArea = selectedArea === 'All' || project.research_area === selectedArea;
    const matchesStatus = selectedStatus === 'All' || project.status === selectedStatus;

    return matchesSearch && matchesArea && matchesStatus;
  });

  const getStatusColor = (status: ProjectStatus) => {
    switch (status) {
      case ProjectStatus.Concept: return 'bg-gray-100 text-gray-800 border-gray-200';
      case ProjectStatus.ProofOfConcept: return 'bg-blue-50 text-blue-700 border-blue-100';
      case ProjectStatus.Prototype: return 'bg-purple-50 text-purple-700 border-purple-100';
      case ProjectStatus.Validation: return 'bg-orange-50 text-orange-700 border-orange-100';
      case ProjectStatus.Commercialization: return 'bg-ug-teal/10 text-ug-teal border-ug-teal/20';
      case ProjectStatus.MarketReady: return 'bg-green-50 text-green-700 border-green-100';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-10">
          <h1 className="text-3xl font-bold text-ug-navy">Research Projects</h1>
          <p className="mt-2 text-gray-600">Browse groundbreaking research from University of Ghana scholars.</p>
        </div>

        {/* Filters & Search */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200 mb-8">
          <div className="flex flex-col md:flex-row gap-4 items-center justify-between">
            <div className="relative w-full md:w-96">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <input 
                type="text" 
                placeholder="Search projects..." 
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-ug-teal focus:border-transparent"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <div className="flex gap-4 w-full md:w-auto">
              <div className="relative">
                 <select 
                    className="appearance-none bg-gray-50 border border-gray-300 text-gray-700 py-2 px-4 pr-8 rounded-md leading-tight focus:outline-none focus:bg-white focus:border-ug-teal"
                    value={selectedArea}
                    onChange={(e) => setSelectedArea(e.target.value)}
                 >
                    <option value="All">All Research Areas</option>
                    {Object.values(ResearchArea).map(area => (
                       <option key={area} value={area}>{area}</option>
                    ))}
                 </select>
                 <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                    <Filter size={16} />
                 </div>
              </div>

              <div className="relative">
                 <select 
                    className="appearance-none bg-gray-50 border border-gray-300 text-gray-700 py-2 px-4 pr-8 rounded-md leading-tight focus:outline-none focus:bg-white focus:border-ug-teal"
                    value={selectedStatus}
                    onChange={(e) => setSelectedStatus(e.target.value)}
                 >
                    <option value="All">All Statuses</option>
                    {Object.values(ProjectStatus).map(status => (
                       <option key={status} value={status}>{status}</option>
                    ))}
                 </select>
                 <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                    <SlidersHorizontal size={16} />
                 </div>
              </div>
            </div>
          </div>
        </div>

        {/* Results Grid */}
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {filteredProjects.map((project) => (
            <div key={project.id} className="bg-white rounded-xl overflow-hidden shadow-sm hover:shadow-lg transition-shadow duration-300 flex flex-col h-full border border-gray-100">
              <div className="h-56 relative overflow-hidden group">
                 <img 
                    src={project.image_url} 
                    alt={project.title} 
                    className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" 
                 />
                 <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
                 <div className="absolute bottom-4 left-4 text-white">
                    <div className="text-xs font-bold bg-ug-teal/90 px-2 py-1 rounded inline-block mb-1 shadow-sm backdrop-blur-sm">TRL {project.trl}</div>
                    <div className="text-sm opacity-90 font-medium">{project.department}</div>
                 </div>
              </div>
              <div className="p-6 flex-1 flex flex-col">
                <h3 className="text-xl font-bold text-gray-900 mb-2 leading-tight">{project.title}</h3>
                <p className="text-gray-600 text-sm mb-4 line-clamp-3 flex-1">{project.description}</p>

                <div className="mt-4 space-y-3">
                   <div className="flex justify-between text-sm">
                      <span className="text-gray-500">Budget:</span>
                      <span className="font-semibold text-gray-700">{project.budget}</span>
                   </div>
                   <div className="flex justify-between text-sm items-center">
                      <span className="text-gray-500">Status:</span>
                      <span className={`text-xs px-2 py-1 rounded border font-medium ${getStatusColor(project.status)}`}>
                        {project.status}
                      </span>
                   </div>
                </div>

                <button className="mt-6 w-full py-2 border border-ug-navy text-ug-navy font-medium rounded hover:bg-ug-navy hover:text-white transition-colors duration-200">
                   View Details
                </button>
              </div>
            </div>
          ))}
        </div>

        {filteredProjects.length === 0 && (
           <div className="text-center py-20">
              <div className="inline-block p-4 rounded-full bg-gray-100 mb-4">
                 <Search size={32} className="text-gray-400" />
              </div>
              <h3 className="text-lg font-medium text-gray-900">No projects found</h3>
              <p className="text-gray-500 mt-1">Try adjusting your search or filters.</p>
           </div>
        )}
      </div>
    </div>
  );
};

