const App: React.FC = () => {
  const [userRole, setUserRole] = useState<UserRole>(UserRole.Researcher);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);

  const handleLogin = () => {
    setIsAuthenticated(true);
  };

  const handleUserIconClick = () => {
    if (isAuthenticated) {
        // In a real app, this might go to profile or logout
        const shouldLogout = window.confirm("Do you want to logout?");
        if(shouldLogout) setIsAuthenticated(false);
    } else {
        setIsAuthModalOpen(true);
    }
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen font-sans text-gray-900">
        <Navbar 
            userRole={userRole} 
            onRoleSwitch={setUserRole} 
            isAuthenticated={isAuthenticated}
            onUserIconClick={handleUserIconClick}
        />

        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/projects" element={<Projects />} />
            <Route path="/partnerships" element={<PlaceholderPage title="Partnerships & Opportunities" />} />
            <Route path="/products" element={<PlaceholderPage title="Commercial Products" />} />
            <Route path="/news" element={<PlaceholderPage title="News & Announcements" />} />
            <Route 
                path="/dashboard" 
                element={
                    isAuthenticated ? (
                        <Dashboards role={userRole} />
                    ) : (
                        <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50">
                            <h2 className="text-2xl font-bold text-ug-navy mb-4">Access Restricted</h2>
                            <p className="text-gray-600 mb-6">Please login to view the dashboard.</p>
                            <button 
                                onClick={() => setIsAuthModalOpen(true)}
                                className="bg-ug-teal text-white px-6 py-2 rounded-lg hover:bg-opacity-90 transition"
                            >
                                Login
                            </button>
                        </div>
                    )
                } 
            />
            {/* Fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>

        <AuthModal 
            isOpen={isAuthModalOpen} 
            onClose={() => setIsAuthModalOpen(false)}
            onLogin={handleLogin}
        />

        <AIAssistant />
        <Footer />
      </div>
    </Router>
  );
};

