import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import AIAssistant from './components/AIAssistant';
import AuthModal from './components/AuthModal';
import Home from './pages/Home';
import Projects from './pages/Projects';
import ProjectDetail from './pages/ProjectDetail';
import Dashboards from './pages/Dashboards';
import { UserRole } from './types';
import { AlertCircle, X } from 'lucide-react';

// Placeholder components
const PlaceholderPage = ({ title }: { title: string }) => (
  <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-4 text-center">
    <h1 className="text-4xl font-bold text-ug-navy mb-4">{title}</h1>
    <p className="text-gray-600 max-w-md">
      This page is part of the UG Virtual Industry Hub architecture.
    </p>
    <button onClick={() => window.history.back()} className="mt-8 text-ug-teal hover:underline">
      Go Back
    </button>
  </div>
);

// Protected Route Component
const ProtectedRoute: React.FC<{ 
  isAuthenticated: boolean; 
  children: React.ReactNode;
  onUnauthorized: () => void;
}> = ({ isAuthenticated, children, onUnauthorized }) => {
  useEffect(() => {
    if (!isAuthenticated) {
      onUnauthorized();
    }
  }, [isAuthenticated, onUnauthorized]);

  if (!isAuthenticated) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

const AppContent: React.FC = () => {
  // Global auth state
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUserRole, setCurrentUserRole] = useState<UserRole | null>(null);

  // Persona filter for homepage (defaults to Researcher for discovery)
  const [homePersona, setHomePersona] = useState<UserRole>(UserRole.Researcher);

  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [showLoginPrompt, setShowLoginPrompt] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();

  const handleLogin = (role: UserRole) => {
    setIsAuthenticated(true);
    setCurrentUserRole(role);
    setShowLoginPrompt(false);
    // After login, clear any persona filter if it conflicts or just stay on current role
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setCurrentUserRole(null);
    setShowLoginPrompt(false);
    navigate('/');
  };

  const handleUserIconClick = () => {
    if (isAuthenticated) {
      navigate('/dashboard');
    } else {
      setIsAuthModalOpen(true);
    }
  };

  const handleUnauthorizedAccess = () => {
    setShowLoginPrompt(true);
    setIsAuthModalOpen(true);
  };

  return (
    <div className="flex flex-col min-h-screen font-sans text-gray-900">
      <Navbar 
          isAuthenticated={isAuthenticated}
          onUserIconClick={handleUserIconClick}
          onLogout={handleLogout}
      />

      {showLoginPrompt && !isAuthenticated && (
        <div className="bg-amber-500 text-white py-3 px-4 flex items-center justify-center gap-3 animate-fade-in shadow-md relative z-40">
          <AlertCircle size={20} className="shrink-0" />
          <span className="text-xs sm:text-sm font-black uppercase tracking-widest">Authentication Required: Please sign in to access your personal dashboard.</span>
          <button 
            onClick={() => setShowLoginPrompt(false)}
            className="ml-4 p-1 hover:bg-white/10 rounded-full transition"
          >
            <X size={16} />
          </button>
        </div>
      )}

      <main className="flex-grow">
        <Routes>
          <Route 
            path="/" 
            element={
              <Home 
                activePersona={homePersona} 
                onPersonaChange={setHomePersona} 
              />
            } 
          />
          <Route path="/projects" element={<Projects />} />
          <Route path="/projects/:id" element={<ProjectDetail />} />
          <Route path="/products" element={<PlaceholderPage title="Products & Innovations" />} />
          <Route path="/news" element={<PlaceholderPage title="News & Announcements" />} />
          <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute 
                  isAuthenticated={isAuthenticated} 
                  onUnauthorized={handleUnauthorizedAccess}
                >
                  <Dashboards role={currentUserRole || UserRole.Researcher} />
                </ProtectedRoute>
              } 
          />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>

      <AuthModal 
          isOpen={isAuthModalOpen} 
          onClose={() => setIsAuthModalOpen(false)}
          onLogin={handleLogin}
      />

      <AIAssistant />
      <Footer />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, User, Bell, LogIn, LogOut } from 'lucide-react';

interface NavbarProps {
  isAuthenticated: boolean;
  onUserIconClick: () => void;
  onLogout: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ isAuthenticated, onUserIconClick, onLogout }) => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Projects', path: '/projects' },
    { name: 'Products', path: '/products' },
    { name: 'News', path: '/news' },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="bg-ug-navy text-white sticky top-0 z-50 shadow-lg">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <Link to="/" className="flex-shrink-0 flex items-center gap-2 cursor-pointer">
             <div className="w-8 h-8 bg-ug-teal rounded-full flex items-center justify-center font-bold text-white">
                UG
             </div>
             <span className="font-bold text-lg tracking-wide">Industry Hub</span>
          </Link>

          {/* Desktop Menu */}
          <div className="hidden md:block">
            <div className="ml-10 flex items-baseline space-x-4">
              {navLinks.map((link) => (
                <Link
                  key={link.name}
                  to={link.path}
                  className={`px-3 py-2 rounded-md text-sm font-medium transition-colors duration-200 ${
                    isActive(link.path)
                      ? 'bg-ug-teal text-white'
                      : 'text-gray-300 hover:bg-white/10 hover:text-white'
                  }`}
                >
                  {link.name}
                </Link>
              ))}
            </div>
          </div>

          {/* User & Notifications */}
          <div className="hidden md:flex items-center gap-4">
             <button className="p-1 rounded-full hover:bg-white/10 relative">
                <Bell size={20} />
                {isAuthenticated && <span className="absolute top-0 right-0 block h-2 w-2 rounded-full bg-ug-error ring-2 ring-ug-navy"></span>}
             </button>

             {/* User Icon - Acts as Dashboard Link if logged in, Login trigger if not */}
             <div 
                className={`h-9 w-9 rounded-full flex items-center justify-center cursor-pointer transition-colors ${isAuthenticated ? 'bg-ug-teal text-white shadow-lg shadow-ug-teal/50' : 'bg-white/10 text-gray-300 hover:bg-white/20'}`}
                onClick={onUserIconClick}
                title={isAuthenticated ? "Go to Dashboard" : "Login / Register"}
             >
                {isAuthenticated ? <User size={18} /> : <LogIn size={18} />}
             </div>

             {isAuthenticated && (
                <button 
                  onClick={onLogout}
                  className="text-gray-400 hover:text-white transition"
                  title="Logout"
                >
                  <LogOut size={20} />
                </button>
             )}
          </div>

          {/* Mobile menu button */}
          <div className="-mr-2 flex md:hidden">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="inline-flex items-center justify-center p-2 rounded-md text-gray-400 hover:text-white hover:bg-gray-700 focus:outline-none"
            >
              {isOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3 bg-ug-navy border-t border-gray-700">
            {navLinks.map((link) => (
              <Link
                key={link.name}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-2 rounded-md text-base font-medium ${
                  isActive(link.path)
                    ? 'bg-ug-teal text-white'
                    : 'text-gray-300 hover:bg-gray-700 hover:text-white'
                }`}
              >
                {link.name}
              </Link>
            ))}
             <div className="mt-4 pt-4 border-t border-gray-700 space-y-3">
               <button 
                  onClick={() => { setIsOpen(false); onUserIconClick(); }}
                  className={`w-full flex items-center gap-2 px-3 py-2 rounded-md ${isAuthenticated ? 'bg-ug-teal text-white' : 'text-gray-300 hover:text-white'}`}
               >
                  <User size={18} />
                  <span>{isAuthenticated ? 'My Dashboard' : 'Login / Register'}</span>
               </button>

               {isAuthenticated && (
                 <button 
                    onClick={() => { setIsOpen(false); onLogout(); }}
                    className="w-full flex items-center gap-2 px-3 py-2 text-gray-300 hover:text-white"
                 >
                    <LogOut size={18} />
                    <span>Logout</span>
                 </button>
               )}
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { X, Mail, Lock, User, ArrowRight } from 'lucide-react';
import { UserRole } from '../types';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLogin: (role: UserRole) => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.Researcher);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, validation and API call would happen here
    // For this demo, we use the selected role to populate the dashboard view
    onLogin(role);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      {/* Modal Content */}
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
        {/* Header Image/Color */}
        <div className="h-32 bg-ug-navy relative overflow-hidden flex items-center justify-center">
            <div className="absolute inset-0 opacity-20 bg-[url('https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=800&q=80')] bg-cover bg-center"></div>
            <div className="relative z-10 text-center">
                <div className="w-12 h-12 bg-ug-teal rounded-full flex items-center justify-center font-bold text-white text-xl mx-auto mb-2 shadow-lg border-2 border-white">
                    UG
                </div>
                <h2 className="text-white font-bold text-xl tracking-wide">Industry Hub</h2>
            </div>
            <button 
                onClick={onClose}
                className="absolute top-4 right-4 text-white/70 hover:text-white transition"
            >
                <X size={24} />
            </button>
        </div>

        {/* Form Container */}
        <div className="p-8">
            <div className="flex border-b border-gray-100 mb-6">
                <button 
                    className={`flex-1 pb-3 text-sm font-medium transition-colors ${isLogin ? 'text-ug-teal border-b-2 border-ug-teal' : 'text-gray-400'}`}
                    onClick={() => setIsLogin(true)}
                >
                    Login
                </button>
                <button 
                    className={`flex-1 pb-3 text-sm font-medium transition-colors ${!isLogin ? 'text-ug-teal border-b-2 border-ug-teal' : 'text-gray-400'}`}
                    onClick={() => setIsLogin(false)}
                >
                    Register
                </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
                {!isLogin && (
                    <div className="space-y-4">
                        <div className="relative">
                            <User className="absolute left-3 top-3 text-gray-400" size={18} />
                            <input 
                                type="text" 
                                placeholder="Full Name"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm"
                            />
                        </div>
                    </div>
                )}

                {/* Role selection is always required for demo login/register to choose the portal */}
                <div className="relative">
                   <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1">Select Persona</label>
                   <select 
                      value={role}
                      onChange={(e) => setRole(e.target.value as UserRole)}
                      className="w-full pl-3 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm bg-white font-bold"
                   >
                      {Object.values(UserRole).map(r => (
                         <option key={r} value={r}>{r}</option>
                      ))}
                   </select>
                </div>

                <div className="relative">
                    <Mail className="absolute left-3 top-3 text-gray-400" size={18} />
                    <input 
                        type="email" 
                        placeholder="Email Address"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm"
                    />
                </div>

                <div className="relative">
                    <Lock className="absolute left-3 top-3 text-gray-400" size={18} />
                    <input 
                        type="password" 
                        placeholder="Password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm"
                    />
                </div>

                <button 
                    type="submit" 
                    className="w-full bg-ug-navy text-white py-3 rounded-lg font-medium hover:bg-opacity-90 transition flex items-center justify-center gap-2 mt-2"
                >
                    {isLogin ? 'Sign In' : 'Create Account'} <ArrowRight size={18} />
                </button>
            </form>

            <p className="text-center text-xs text-gray-400 mt-6">
                By continuing, you agree to University of Ghana's Terms of Service and Privacy Policy.
            </p>
        </div>
      </div>
    </div>
  );
};

export default AuthModal;

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import AIAssistant from './components/AIAssistant';
import AuthModal from './components/AuthModal';
import Home from './pages/Home';
import Projects from './pages/Projects';
import ProjectDetail from './pages/ProjectDetail';
import Dashboards from './pages/Dashboards';
import { UserRole } from './types';
import { AlertCircle, X } from 'lucide-react';

// Protected Route Component: Restricts access to authenticated users
const ProtectedRoute: React.FC<{ 
  isAuthenticated: boolean; 
  children: React.ReactNode;
  onUnauthorized: () => void;
}> = ({ isAuthenticated, children, onUnauthorized }) => {
  const location = useLocation();

  useEffect(() => {
    if (!isAuthenticated && location.pathname === '/dashboard') {
      onUnauthorized();
    }
  }, [isAuthenticated, location.pathname, onUnauthorized]);

  if (!isAuthenticated) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

const AppContent: React.FC = () => {
  // 1. Authenticated state: The "Real" identity
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userAccountRole, setUserAccountRole] = useState<UserRole | null>(null);

  // 2. Discovery state: A "View-As" filter strictly for the homepage
  const [discoveryPersona, setDiscoveryPersona] = useState<UserRole>(UserRole.Researcher);

  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [showLoginPrompt, setShowLoginPrompt] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();

  const handleLogin = (role: UserRole) => {
    setIsAuthenticated(true);
    setUserAccountRole(role);
    setShowLoginPrompt(false);
    // When logging in, we automatically sync the homepage persona to the user's role for consistency
    setDiscoveryPersona(role);
    navigate('/dashboard');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUserAccountRole(null);
    setShowLoginPrompt(false);
    navigate('/');
  };

  const handleUserIconClick = () => {
    if (isAuthenticated) {
      navigate('/dashboard');
    } else {
      setIsAuthModalOpen(true);
    }
  };

  const handleUnauthorizedAccess = () => {
    setShowLoginPrompt(true);
    setIsAuthModalOpen(true);
  };

  return (
    <div className="flex flex-col min-h-screen font-sans text-gray-900">
      <Navbar 
          isAuthenticated={isAuthenticated}
          onUserIconClick={handleUserIconClick}
          onLogout={handleLogout}
      />

      {/* Access Denied / Login Prompt Banner */}
      {showLoginPrompt && !isAuthenticated && (
        <div className="bg-ug-error text-white py-3 px-4 flex items-center justify-center gap-3 animate-fade-in shadow-xl relative z-40">
          <AlertCircle size={20} className="shrink-0" />
          <span className="text-xs sm:text-sm font-black uppercase tracking-widest">
            Identity Required: Please sign in to access your secure {userAccountRole || 'user'} dashboard.
          </span>
          <button 
            onClick={() => setShowLoginPrompt(false)}
            className="ml-4 p-1 hover:bg-white/10 rounded-full transition"
          >
            <X size={16} />
          </button>
        </div>
      )}

      <main className="flex-grow">
        <Routes>
          <Route 
            path="/" 
            element={
              <Home 
                activePersona={discoveryPersona} 
                onPersonaChange={setDiscoveryPersona} 
              />
            } 
          />
          <Route path="/projects" element={<Projects />} />
          <Route path="/projects/:id" element={<ProjectDetail />} />
          <Route path="/products" element={
            <div className="min-h-screen flex items-center justify-center p-8 bg-gray-50">
              <div className="text-center max-w-xl">
                <h2 className="text-4xl font-black text-ug-navy mb-4">Innovation Catalog</h2>
                <p className="text-gray-600">This directory showcases market-ready products from UG research. Full access is restricted to verified industry partners.</p>
              </div>
            </div>
          } />
          <Route path="/news" element={<div className="p-20 text-center font-bold">University Research News Portal</div>} />

          {/* SECURE DASHBOARD ROUTE */}
          <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute 
                  isAuthenticated={isAuthenticated} 
                  onUnauthorized={handleUnauthorizedAccess}
                >
                  <Dashboards role={userAccountRole || UserRole.Researcher} />
                </ProtectedRoute>
              } 
          />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>

      <AuthModal 
          isOpen={isAuthModalOpen} 
          onClose={() => setIsAuthModalOpen(false)}
          onLogin={handleLogin}
      />

      <AIAssistant />
      <Footer />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;

