import { AlertCircle, X } from 'lucide-react';

// Protected Route Component: Restricts access to authenticated users
const ProtectedRoute: React.FC<{ 
  isAuthenticated: boolean; 
  children: React.ReactNode;
  onUnauthorized: () => void;
}> = ({ isAuthenticated, children, onUnauthorized }) => {
  const location = useLocation();

  useEffect(() => {
    if (!isAuthenticated && location.pathname === '/dashboard') {
      onUnauthorized();
    }
  }, [isAuthenticated, location.pathname, onUnauthorized]);

  if (!isAuthenticated) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

const AppContent: React.FC = () => {
  // 1. Authenticated state: The "Real" identity
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userAccountRole, setUserAccountRole] = useState<UserRole | null>(null);

  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [showLoginPrompt, setShowLoginPrompt] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();

  const handleLogin = (role: UserRole) => {
    setIsAuthenticated(true);
    setUserAccountRole(role);
    setShowLoginPrompt(false);
    navigate('/dashboard');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUserAccountRole(null);
    setShowLoginPrompt(false);
    navigate('/');
  };

  const handleUserIconClick = () => {
    if (isAuthenticated) {
      navigate('/dashboard');
    } else {
      setIsAuthModalOpen(true);
    }
  };

  const handleUnauthorizedAccess = () => {
    setShowLoginPrompt(true);
    setIsAuthModalOpen(true);
  };

  return (
    <div className="flex flex-col min-h-screen font-sans text-gray-900">
      <Navbar 
          isAuthenticated={isAuthenticated}
          onUserIconClick={handleUserIconClick}
          onLogout={handleLogout}
      />

      {/* Access Denied / Login Prompt Banner */}
      {showLoginPrompt && !isAuthenticated && (
        <div className="bg-ug-error text-white py-3 px-4 flex items-center justify-center gap-3 animate-fade-in shadow-xl relative z-40">
          <AlertCircle size={20} className="shrink-0" />
          <span className="text-xs sm:text-sm font-black uppercase tracking-widest">
            Identity Required: Please sign in to access your secure {userAccountRole || 'user'} dashboard.
          </span>
          <button 
            onClick={() => setShowLoginPrompt(false)}
            className="ml-4 p-1 hover:bg-white/10 rounded-full transition"
          >
            <X size={16} />
          </button>
        </div>
      )}

      <main className="flex-grow">
        <Routes>
          <Route 
            path="/" 
            element={
              <Home />
            } 
          />
          <Route path="/projects" element={<Projects />} />
          <Route path="/projects/:id" element={<ProjectDetail />} />
          <Route path="/products" element={
            <div className="min-h-screen flex items-center justify-center p-8 bg-gray-50">
              <div className="text-center max-w-xl">
                <h2 className="text-4xl font-black text-ug-navy mb-4">Innovation Catalog</h2>
                <p className="text-gray-600">This directory showcases market-ready products from UG research. Full access is restricted to verified industry partners.</p>
              </div>
            </div>
          } />
          <Route path="/news" element={<div className="p-20 text-center font-bold">University Research News Portal</div>} />

          {/* SECURE DASHBOARD ROUTE */}
          <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute 
                  isAuthenticated={isAuthenticated} 
                  onUnauthorized={handleUnauthorizedAccess}
                >
                  <Dashboards role={userAccountRole || UserRole.Researcher} />
                </ProtectedRoute>
              } 
          />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>

      <AuthModal 
          isOpen={isAuthModalOpen} 
          onClose={() => setIsAuthModalOpen(false)}
          onLogin={handleLogin}
      />

      <AIAssistant />
      <Footer />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;

import { Project, NewsItem, User, UserRole } from '../types';
import { PROJECTS as INITIAL_PROJECTS, LATEST_NEWS as INITIAL_NEWS } from '../constants';

const DB_KEYS = {
  PROJECTS: 'ug_hub_projects',
  NEWS: 'ug_hub_news',
  EOIS: 'ug_hub_eois',
  USER: 'ug_hub_current_user'
};

export const StorageService = {
  // Initialization: Seed data if empty
  init: () => {
    if (!localStorage.getItem(DB_KEYS.PROJECTS)) {
      localStorage.setItem(DB_KEYS.PROJECTS, JSON.stringify(INITIAL_PROJECTS));
    }
    if (!localStorage.getItem(DB_KEYS.NEWS)) {
      localStorage.setItem(DB_KEYS.NEWS, JSON.stringify(INITIAL_NEWS));
    }
    if (!localStorage.getItem(DB_KEYS.EOIS)) {
      localStorage.setItem(DB_KEYS.EOIS, JSON.stringify([]));
    }
  },

  // Projects CRUD
  getProjects: (): Project[] => {
    const data = localStorage.getItem(DB_KEYS.PROJECTS);
    return data ? JSON.parse(data) : [];
  },

  saveProject: (project: Project) => {
    const projects = StorageService.getProjects();
    const index = projects.findIndex(p => p.id === project.id);
    if (index >= 0) {
      projects[index] = project;
    } else {
      projects.push({ ...project, id: `p-${Date.now()}` });
    }
    localStorage.setItem(DB_KEYS.PROJECTS, JSON.stringify(projects));
    return project;
  },

  deleteProject: (id: string) => {
    const projects = StorageService.getProjects().filter(p => p.id !== id);
    localStorage.setItem(DB_KEYS.PROJECTS, JSON.stringify(projects));
  },

  // News CRUD
  getNews: (): NewsItem[] => {
    const data = localStorage.getItem(DB_KEYS.NEWS);
    return data ? JSON.parse(data) : [];
  },

  saveNewsItem: (item: NewsItem) => {
    const news = StorageService.getNews();
    news.unshift({ ...item, id: `n-${Date.now()}` });
    localStorage.setItem(DB_KEYS.NEWS, JSON.stringify(news));
  },

  // Expressions of Interest (EOIs)
  submitEOI: (project_id: string, user_name: string, message: string) => {
    const eois = JSON.parse(localStorage.getItem(DB_KEYS.EOIS) || '[]');
    eois.unshift({
      id: `eoi-${Date.now()}`,
      project_id,
      user_name,
      message,
      date: new Date().toISOString(),
      read: false
    });
    localStorage.setItem(DB_KEYS.EOIS, JSON.stringify(eois));
  },

  getEOIs: () => {
    return JSON.parse(localStorage.getItem(DB_KEYS.EOIS) || '[]');
  }
};

