export const StorageService = {
  // Initialization: In Supabase, this might involve checking session
  init: async () => {
    // No explicit seeding needed as data lives in the cloud
    const { data: { session } } = await supabase.auth.getSession();
    return session;
  },

  // Projects CRUD
  getProjects: async (): Promise<Project[]> => {
    const { data, error } = await supabase
      .from('projects')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Error fetching projects:', error);
      return [];
    }
    return data || [];
  },

  saveProject: async (project: Partial<Project>) => {
    const { data, error } = await supabase
      .from('projects')
      .upsert(project)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  deleteProject: async (id: string) => {
    const { error } = await supabase
      .from('projects')
      .delete()
      .eq('id', id);

    if (error) throw error;
  },

  // News CRUD
  getNews: async (): Promise<NewsItem[]> => {
    const { data, error } = await supabase
      .from('news')
      .select('*')
      .order('published_at', { ascending: false });

    if (error) {
      console.error('Error fetching news:', error);
      return [];
    }
    return data || [];
  },

  saveNewsItem: async (item: Partial<NewsItem>) => {
    const { data, error } = await supabase
      .from('news')
      .upsert(item)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  // Expressions of Interest (EOIs)
  submitEOI: async (project_id: string, user_name: string, message: string) => {
    const { error } = await supabase
      .from('eois')
      .insert([{
        project_id,
        user_name,
        message,
        read: false
      }]);

    if (error) throw error;
  },

  getEOIs: async () => {
    const { data, error } = await supabase
      .from('eois')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Error fetching EOIs:', error);
      return [];
    }
    return data || [];
  },

  // Profile Management
  getProfile: async (userId: string) => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();

    if (error) return null;
    return data;
  },

  updateProfile: async (profile: Partial<User>) => {
    const { error } = await supabase
      .from('profiles')
      .upsert(profile);

    if (error) throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import AIAssistant from './components/AIAssistant';
import AuthModal from './components/AuthModal';
import Home from './pages/Home';
import Projects from './pages/Projects';
import ProjectDetail from './pages/ProjectDetail';
import Dashboards from './pages/Dashboards';
import Products from './pages/Products';
import News from './pages/News';
import Privacy from './pages/Privacy';
import Terms from './pages/Terms';
import { UserRole, User } from './types';
import { AlertCircle, X } from 'lucide-react';
import { supabase } from './lib/supabase';
import { StorageService } from './services/storageService';

// Protected Route Component
const ProtectedRoute: React.FC<{ 
  isAuthenticated: boolean; 
  children: React.ReactNode;
  onUnauthorized: () => void;
}> = ({ isAuthenticated, children, onUnauthorized }) => {
  const location = useLocation();

  useEffect(() => {
    if (!isAuthenticated && location.pathname === '/dashboard') {
      onUnauthorized();
    }
  }, [isAuthenticated, location.pathname, onUnauthorized]);

  if (!isAuthenticated) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

const AppContent: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userProfile, setUserProfile] = useState<User | null>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [showLoginPrompt, setShowLoginPrompt] = useState(false);

  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    // Check active sessions and set up auth listener
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        setIsAuthenticated(true);
        loadProfile(session.user.id);
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        setIsAuthenticated(true);
        loadProfile(session.user.id);
      } else {
        setIsAuthenticated(false);
        setUserProfile(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const loadProfile = async (userId: string) => {
    const profile = await StorageService.getProfile(userId);
    if (profile) {
      setUserProfile(profile);
    } else {
      // Default fallback if profile record doesn't exist yet
      setUserProfile({ id: userId, email: '', name: 'Researcher', role: UserRole.Researcher });
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    navigate('/');
  };

  const handleUserIconClick = () => {
    if (isAuthenticated) {
      navigate('/dashboard');
    } else {
      setIsAuthModalOpen(true);
    }
  };

  const handleUnauthorizedAccess = () => {
    setShowLoginPrompt(true);
    setIsAuthModalOpen(true);
  };

  return (
    <div className="flex flex-col min-h-screen font-sans text-gray-900">
      <Navbar 
          isAuthenticated={isAuthenticated}
          onUserIconClick={handleUserIconClick}
          onLogout={handleLogout}
      />

      {showLoginPrompt && !isAuthenticated && (
        <div className="bg-ug-error text-white py-3 px-4 flex items-center justify-center gap-3 animate-fade-in shadow-xl relative z-40">
          <AlertCircle size={20} className="shrink-0" />
          <span className="text-xs sm:text-sm font-black uppercase tracking-widest">
            Security: Please sign in to access your secure innovation command center.
          </span>
          <button 
            onClick={() => setShowLoginPrompt(false)}
            className="ml-4 p-1 hover:bg-white/10 rounded-full transition"
          >
            <X size={16} />
          </button>
        </div>
      )}

      <main className="flex-grow">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/projects" element={<Projects />} />
          <Route path="/projects/:id" element={<ProjectDetail />} />
          <Route path="/products" element={<Products />} />
          <Route path="/news" element={<News />} />
          <Route path="/privacy" element={<Privacy />} />
          <Route path="/terms" element={<Terms />} />

          <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute 
                  isAuthenticated={isAuthenticated} 
                  onUnauthorized={handleUnauthorizedAccess}
                >
                  <Dashboards role={userProfile?.role || UserRole.Researcher} />
                </ProtectedRoute>
              } 
          />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>

      <AuthModal 
          isOpen={isAuthModalOpen} 
          onClose={() => setIsAuthModalOpen(false)}
      />

      <AIAssistant />
      <Footer />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { X, Mail, Lock, User, ArrowRight, AlertCircle } from 'lucide-react';
import { UserRole } from '../types';
import { supabase } from '../lib/supabase';
import { StorageService } from '../services/storageService';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.Researcher);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (isLogin) {
        const { error: authError } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (authError) throw authError;
      } else {
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email,
          password,
        });
        if (authError) throw authError;

        if (authData.user) {
          // Create profile in profiles table
          await StorageService.updateProfile({
            id: authData.user.id,
            email,
            name: name || 'Anonymous User',
            role: role
          });
        }
      }
      onClose();
    } catch (err: any) {
      setError(err.message || 'An error occurred during authentication.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>

      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
        <div className="h-32 bg-ug-navy relative overflow-hidden flex items-center justify-center">
            <div className="absolute inset-0 opacity-20 bg-[url('https://images.unsplash.com/photo-1532094349884-543bc11b234d?auto=format&fit=crop&w=800&q=80')] bg-cover bg-center"></div>
            <div className="relative z-10 text-center">
                <div className="w-12 h-12 bg-ug-teal rounded-full flex items-center justify-center font-bold text-white text-xl mx-auto mb-2 shadow-lg border-2 border-white">
                    UG
                </div>
                <h2 className="text-white font-bold text-xl tracking-wide">Industry Hub</h2>
            </div>
            <button onClick={onClose} className="absolute top-4 right-4 text-white/70 hover:text-white transition"><X size={24} /></button>
        </div>

        <div className="p-8">
            {error && (
              <div className="mb-6 p-4 bg-red-50 text-red-600 rounded-xl flex items-start gap-3 text-xs font-bold animate-pulse">
                <AlertCircle size={18} className="shrink-0" />
                <span>{error}</span>
              </div>
            )}

            <div className="flex border-b border-gray-100 mb-6">
                <button 
                    className={`flex-1 pb-3 text-sm font-black transition-colors ${isLogin ? 'text-ug-teal border-b-2 border-ug-teal' : 'text-gray-400'}`}
                    onClick={() => setIsLogin(true)}
                >
                    Login
                </button>
                <button 
                    className={`flex-1 pb-3 text-sm font-black transition-colors ${!isLogin ? 'text-ug-teal border-b-2 border-ug-teal' : 'text-gray-400'}`}
                    onClick={() => setIsLogin(false)}
                >
                    Join Hub
                </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
                {!isLogin && (
                    <>
                    <div className="relative">
                        <User className="absolute left-3 top-3 text-gray-400" size={18} />
                        <input required type="text" placeholder="Full Academic/Company Name" value={name} onChange={(e) => setName(e.target.value)} className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm font-bold" />
                    </div>
                    <div className="relative">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-1">Identify Role</label>
                       <select value={role} onChange={(e) => setRole(e.target.value as UserRole)} className="w-full pl-3 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm bg-white font-bold">
                          {Object.values(UserRole).map(r => <option key={r} value={r}>{r}</option>)}
                       </select>
                    </div>
                    </>
                )}

                <div className="relative">
                    <Mail className="absolute left-3 top-3 text-gray-400" size={18} />
                    <input required type="email" placeholder="Email Address" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm font-bold" />
                </div>

                <div className="relative">
                    <Lock className="absolute left-3 top-3 text-gray-400" size={18} />
                    <input required type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-ug-teal/20 focus:border-ug-teal text-sm font-bold" />
                </div>

                <button 
                    type="submit" 
                    disabled={loading}
                    className="w-full bg-ug-navy text-white py-3 rounded-lg font-black uppercase tracking-widest hover:bg-opacity-90 transition flex items-center justify-center gap-2 mt-2 disabled:opacity-50"
                >
                    {loading ? 'Authenticating...' : isLogin ? 'Enter Hub' : 'Create Profile'} <ArrowRight size={18} />
                </button>
            </form>

            <p className="text-center text-[10px] text-gray-400 mt-6 leading-relaxed font-bold uppercase tracking-widest">
                Protected by UG Research Governance & Ghana Data Protection Act (Act 843).
            </p>
        </div>
      </div>
    </div>
  );
};

