                    {project.status}
                  </span>
                  <span className="px-4 py-1 rounded-full text-xs font-black uppercase tracking-widest bg-ug-navy text-white shadow-lg">
                    TRL Level {project.trl}
                  </span>
                </div>
                <h1 className="text-3xl md:text-5xl font-black text-white tracking-tight leading-tight max-w-4xl">
                  {project.title}
                </h1>
                <p className="text-ug-teal font-bold mt-2 uppercase tracking-widest flex items-center gap-2">
                  <Microscope size={18} /> {project.research_area}
