const ProjectFormModal: React.FC<{ isOpen: boolean; onClose: () => void; onSave: () => void }> = ({ isOpen, onClose, onSave }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [area, setArea] = useState<ResearchArea>(ResearchArea.Diagnostics);
  const [status, setStatus] = useState<ProjectStatus>(ProjectStatus.Concept);
  const [trl, setTrl] = useState<number>(1);
  const [mainImage, setMainImage] = useState('https://images.unsplash.com/photo-1576086213369-97a306d36557?auto=format&fit=crop&w=800&q=80');
  const [secondImage, setSecondImage] = useState('');
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      // Combine images with a delimiter to store in single column
      const combinedImages = secondImage.trim() 
        ? `${mainImage}|${secondImage.trim()}`
        : mainImage;

      await StorageService.saveProject({
        title,
        description,
        research_area: area,
        status,
        department: 'UG Innovation Hub',
        trl: trl,
        visibility: Visibility.Public,
        budget: 'TBD',
        start_date: new Date().toISOString().split('T')[0],
        image_url: combinedImages,
        // impact_metrics removed to fix schema error
      });
      onSave();
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-ug-navy/80 backdrop-blur-sm">
      <div className="bg-white rounded-[2rem] w-full max-w-2xl p-8 shadow-2xl max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-8 border-b border-gray-100 pb-4">
          <div>
            <h2 className="text-2xl font-black text-ug-navy">New Research Disclosure</h2>
            <p className="text-xs text-gray-400 uppercase tracking-widest font-bold mt-1">Submit innovation for review</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition"><X /></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Project Title</label>
            <input 
              required 
              placeholder="e.g. Novel Malaria Diagnostic Kit" 
              value={title} 
              onChange={e => setTitle(e.target.value)} 
              className="w-full bg-gray-50 border border-gray-200 rounded-xl p-4 focus:outline-none focus:ring-2 focus:ring-ug-teal/20 font-bold text-lg" 
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
               <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Research Area (Type)</label>
               <div className="relative">
                 <select 
                    value={area} 
                    onChange={e => setArea(e.target.value as ResearchArea)} 
                    className="w-full bg-gray-50 border border-gray-200 rounded-xl p-4 appearance-none font-bold text-gray-700 focus:outline-none focus:ring-2 focus:ring-ug-teal/20"
                 >
                    {Object.values(ResearchArea).map(a => <option key={a} value={a}>{a}</option>)}
                 </select>
                 <ChevronRight className="absolute right-4 top-1/2 -translate-y-1/2 rotate-90 text-gray-400" size={16} />
               </div>
            </div>

            <div className="space-y-2">
               <label className="text-xs font-black text-ug-navy uppercase tracking-widest">TRL Level (1-9)</label>
               <div className="relative">
                 <select 
                    value={trl} 
                    onChange={e => setTrl(Number(e.target.value))} 
                    className="w-full bg-gray-50 border border-gray-200 rounded-xl p-4 appearance-none font-bold text-gray-700 focus:outline-none focus:ring-2 focus:ring-ug-teal/20"
                 >
                    {[1,2,3,4,5,6,7,8,9].map(num => (
                      <option key={num} value={num}>TRL {num}</option>
                    ))}
                 </select>
                 <ChevronRight className="absolute right-4 top-1/2 -translate-y-1/2 rotate-90 text-gray-400" size={16} />
               </div>
            </div>
          </div>

           {/* IMAGE UPLOAD SECTION */}
          <div className="space-y-4 pt-4 border-t border-gray-50">
