import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { 
  ArrowLeft, Calendar, DollarSign, Microscope, ShieldCheck, TrendingUp, 
  Users, Bookmark, FileText, CheckCircle2, AlertCircle, Send, Check, Image as ImageIcon
} from 'lucide-react';
import { StorageService } from '../services/storageService';
import { Project, ProjectStatus } from '../types';

const ProjectDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [project, setProject] = useState<Project | null>(null);
  const [isEoiSubmitting, setIsEoiSubmitting] = useState(false);
  const [eoiSent, setEoiSent] = useState(false);
  const [isBookmarked, setIsBookmarked] = useState(false);

  useEffect(() => {
    const fetchProject = async () => {
      if (id) {
        const projects = await StorageService.getProjects();
        const data = projects.find(p => p.id === id);
        if (data) setProject(data);
      }
    };
    fetchProject();
  }, [id]);

  if (!project) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4">
        <h2 className="text-2xl font-bold text-ug-navy mb-4">Project Not Found</h2>
        <Link to="/projects" className="text-ug-teal flex items-center gap-2 hover:underline">
          <ArrowLeft size={18} /> Back to Projects
        </Link>
      </div>
    );
  }

  const handleEoiSubmit = () => {
    setIsEoiSubmitting(true);
    setTimeout(() => {
      StorageService.submitEOI(
        project.id, 
        "Industry Partner Account", 
        `Expression of Interest submitted for "${project.title}". We are interested in discussing commercialization paths.`
      );
      setIsEoiSubmitting(false);
      setEoiSent(true);
    }, 1500);
  };

  const getStatusColor = (status: ProjectStatus) => {
    switch (status) {
      case ProjectStatus.Concept: return 'bg-gray-100 text-gray-800 border-gray-200';
      case ProjectStatus.ProofOfConcept: return 'bg-blue-50 text-blue-700 border-blue-100';
      case ProjectStatus.Prototype: return 'bg-purple-50 text-purple-700 border-purple-100';
      case ProjectStatus.Validation: return 'bg-orange-50 text-orange-700 border-orange-100';
      case ProjectStatus.Commercialization: return 'bg-ug-teal/10 text-ug-teal border-ug-teal/20';
      case ProjectStatus.MarketReady: return 'bg-green-50 text-green-700 border-green-100';
