                 <div className="absolute bottom-4 left-6 text-white">
                    <div className="text-[10px] font-black bg-ug-teal px-3 py-1 rounded-full inline-block mb-2 shadow-xl backdrop-blur-md tracking-widest uppercase">TRL {project.trl}</div>
                    <div className="text-xs opacity-90 font-bold uppercase tracking-widest">{project.department}</div>
