const ProjectFormModal: React.FC<{ isOpen: boolean; onClose: () => void; onSave: () => void }> = ({ isOpen, onClose, onSave }) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [area, setArea] = useState<ResearchArea>(ResearchArea.Diagnostics);
  const [status, setStatus] = useState<ProjectStatus>(ProjectStatus.Concept);
  const [trl, setTrl] = useState<number>(1);

  // New Fields
  const [openCollaboration, setOpenCollaboration] = useState(false);
  const [fundingAmount, setFundingAmount] = useState<string>('');

  // Files
  const [mainImageFile, setMainImageFile] = useState<File | null>(null);
  const [secondImageFile, setSecondImageFile] = useState<File | null>(null);
  const [techDocFile, setTechDocFile] = useState<File | null>(null);

  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleDescriptionChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const words = e.target.value.split(/\s+/).filter(Boolean).length;
    if (words <= 300) { // Increased word count limit
      setDescription(e.target.value);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // 1. Upload Images - Using UPPERCASE bucket names to match Supabase Screenshot
      let img1Url = 'https://images.unsplash.com/photo-1576086213369-97a306d36557?auto=format&fit=crop&w=800&q=80'; // Fallback
      let img2Url = '';

      if (mainImageFile) {
        img1Url = await StorageService.uploadFile(mainImageFile, 'PROJECT-IMAGES');
      }
      if (secondImageFile) {
        img2Url = await StorageService.uploadFile(secondImageFile, 'PROJECT-IMAGES');
      }

      const combinedImages = img2Url ? `${img1Url}|${img2Url}` : img1Url;

      // 2. Upload Tech Doc - Using UPPERCASE bucket names
      let techDocUrl = '';
      if (techDocFile) {
        techDocUrl = await StorageService.uploadFile(techDocFile, 'TECHNICAL-DOCS');
      }

      // 3. Prepare Description with Merged Data
      // WORKAROUND: Since DB lacks columns for funding/collaboration, we append them to description
      let finalDescription = description;
      const extras = [];
      if (openCollaboration) extras.push("Open to Collaboration: YES");
      if (fundingAmount) extras.push(`Funding Required: $${fundingAmount}`);
      if (techDocUrl) extras.push(`Technical Doc: Available (Restricted)`);

      if (extras.length > 0) {
        finalDescription += `\n\n--- Project Requirements ---\n${extras.join('\n')}`;
      }

      // 4. Save to DB
      await StorageService.saveProject({
        title,
        description: finalDescription,
        research_area: area,
        status,
        department: 'UG Innovation Hub',
        trl: trl,
        visibility: Visibility.Public,
        start_date: new Date().toISOString().split('T')[0],
        image_url: combinedImages,
        budget: fundingAmount ? `$${fundingAmount}` : 'TBD'
        // Removed fields that don't exist in DB to prevent errors
      });

      onSave();
      onClose();
    } catch (err) {
      console.error(err);
      alert("Failed to save. Please check your internet connection or try a smaller image.");
    } finally {
      setLoading(false);
    }
  };

  const wordCount = description.split(/\s+/).filter(Boolean).length;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-ug-navy/80 backdrop-blur-sm">
      <div className="bg-white rounded-[2rem] w-full max-w-3xl p-8 shadow-2xl max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-8 border-b border-gray-100 pb-4">
          <div>
            <h2 className="text-2xl font-black text-ug-navy">New Research Disclosure</h2>
            <p className="text-xs text-gray-400 uppercase tracking-widest font-bold mt-1">Submit innovation for review</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition"><X /></button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-8">

          {/* Section 1: Core Details */}
          <div className="space-y-4">
            <h3 className="text-sm font-black text-ug-teal uppercase tracking-widest border-b border-gray-100 pb-2">1. Core Information</h3>
            <div className="space-y-2">
              <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Project Title</label>
              <input 
                required 
                placeholder="e.g. Novel Malaria Diagnostic Kit" 
                value={title} 
                onChange={e => setTitle(e.target.value)} 
                className="w-full bg-gray-50 border border-gray-200 rounded-xl p-4 focus:outline-none focus:ring-2 focus:ring-ug-teal/20 font-bold text-lg" 
              />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                 <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Research Type</label>
                 <select 
                    value={area} 
                    onChange={e => setArea(e.target.value as ResearchArea)} 
                    className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 font-bold text-gray-700"
                 >
                    {Object.values(ResearchArea).map(a => <option key={a} value={a}>{a}</option>)}
                 </select>
              </div>

              <div className="space-y-2">
                 <label className="text-xs font-black text-ug-navy uppercase tracking-widest">TRL Level (1-9)</label>
                 <select 
                    value={trl} 
                    onChange={e => setTrl(Number(e.target.value))} 
                    className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 font-bold text-gray-700"
                 >
                    {[1,2,3,4,5,6,7,8,9].map(num => (
                      <option key={num} value={num}>TRL {num}</option>
                    ))}
                 </select>
              </div>
            </div>
          </div>

          {/* Section 2: Description */}
          <div className="space-y-4">
            <h3 className="text-sm font-black text-ug-teal uppercase tracking-widest border-b border-gray-100 pb-2">2. Abstract</h3>
            <div className="space-y-2">
              <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Description (Max 300 words)</label>
              <textarea 
                required 
                placeholder="Briefly describe the innovation, methodology, and expected impact..." 
                rows={6} 
                value={description} 
                onChange={handleDescriptionChange}
                className="w-full bg-gray-50 border border-gray-200 rounded-xl p-4 focus:outline-none focus:ring-2 focus:ring-ug-teal/20 font-medium text-gray-600 resize-none" 
              />
              <div className={`text-[10px] font-bold text-right uppercase ${wordCount >= 300 ? 'text-red-500' : 'text-gray-400'}`}>
                 {wordCount} / 300 words
              </div>
            </div>
          </div>

          {/* Section 3: Collaboration & Funding */}
          <div className="space-y-4">
            <h3 className="text-sm font-black text-ug-teal uppercase tracking-widest border-b border-gray-100 pb-2">3. Needs & Partnership</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-start">

               <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <div className={`w-6 h-6 rounded flex items-center justify-center border transition ${openCollaboration ? 'bg-ug-teal border-ug-teal text-white' : 'bg-white border-gray-300'}`}>
                      {openCollaboration && <Check size={14} />}
                    </div>
                    <input type="checkbox" className="hidden" checked={openCollaboration} onChange={e => setOpenCollaboration(e.target.checked)} />
                    <div>
                       <span className="text-xs font-black text-ug-navy uppercase block">Open to Collaboration</span>
                       <span className="text-[10px] text-gray-400">Seeking partners/mentors</span>
                    </div>
                  </label>
               </div>

               <div className="space-y-2">
                  <label className="text-xs font-black text-ug-navy uppercase tracking-widest flex items-center gap-1">
                    <DollarSign size={14} /> Open to Funding (USD)
                  </label>
                  <input 
                    type="number"
                    placeholder="e.g. 50000"
                    value={fundingAmount}
                    onChange={e => setFundingAmount(e.target.value)}
                    className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 font-bold text-gray-700"
                  />
               </div>
            </div>
          </div>

          {/* Section 4: File Uploads */}
          <div className="space-y-4">
             <h3 className="text-sm font-black text-ug-teal uppercase tracking-widest border-b border-gray-100 pb-2">4. Attachments</h3>

             {/* Images */}
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <div className="space-y-2">
                  <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Main Image (Required)</label>
                  <div className="relative">
                    <input 
                      type="file" 
                      required 
                      accept="image/*"
                      onChange={e => setMainImageFile(e.target.files?.[0] || null)}
                      className="w-full text-xs text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-black file:bg-ug-navy/10 file:text-ug-navy hover:file:bg-ug-navy/20"
                    />
                  </div>
               </div>
               <div className="space-y-2">
                  <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Secondary Image</label>
                  <input 
                    type="file" 
                    accept="image/*"
                    onChange={e => setSecondImageFile(e.target.files?.[0] || null)}
                    className="w-full text-xs text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-black file:bg-ug-navy/10 file:text-ug-navy hover:file:bg-ug-navy/20"
                  />
               </div>
             </div>

             {/* Technical Docs */}
             <div className="bg-amber-50 p-4 rounded-xl border border-amber-100 space-y-2">
                <div className="flex items-center gap-2 mb-2">
                   <FileCode size={16} className="text-amber-600" />
                   <label className="text-xs font-black text-amber-800 uppercase tracking-widest">Protected Technical Details</label>
                </div>
                <p className="text-[10px] text-amber-700/80 mb-3 font-medium">
                   Upload a PDF, PPT, or ZIP containing in-depth research data. This file is <strong>hidden from the public</strong> and only shared with partners who submit an approved EOI.
                </p>
                <input 
                  type="file" 
                  accept=".pdf,.ppt,.pptx,.zip"
                  onChange={e => setTechDocFile(e.target.files?.[0] || null)}
                  className="w-full text-xs text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-black file:bg-amber-200 file:text-amber-900 hover:file:bg-amber-300"
                />
             </div>
          </div>

          <div className="pt-4 border-t border-gray-100">
             <button disabled={loading} type="submit" className="w-full bg-ug-navy text-white py-4 rounded-xl font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 hover:bg-ug-teal transition-colors">
               {loading ? <Loader2 className="animate-spin" /> : 'Register Innovation'}
             </button>
          </div>
        </form>
      </div>
    </div>
  );
};

