import { Project, NewsItem, User, UserRole } from '../types';
import { supabase } from '../lib/supabase';

export const StorageService = {
  // Initialization
  init: async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      return session;
    } catch (error) {
      console.error('Session initialization error:', error);
      return null;
    }
  },

  // --- FILE UPLOAD LOGIC ---
  uploadFile: async (file: File, bucket: string): Promise<string> => {
    // 1. Sanitize file name
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${fileExt}`;
    const filePath = `${fileName}`;

    // 2. Upload
    const { error: uploadError } = await supabase.storage
      .from(bucket)
      .upload(filePath, file);

    if (uploadError) {
      console.error(`Upload failed for bucket ${bucket}:`, uploadError);
      throw uploadError;
    }

    // 3. Get Public URL (Only works for public buckets, but method exists for private too)
    // For private buckets (TECHNICAL-DOCS), we typically use createSignedUrl, 
    // but for simplicity in this MVP we store the path or public URL.
    // If the bucket is private, getPublicUrl returns a URL that might 403 unless signed, 
    // but we need a string reference for the DB.
    const { data } = supabase.storage.from(bucket).getPublicUrl(filePath);
    return data.publicUrl;
  },

  // Projects CRUD
  getProjects: async (): Promise<Project[]> => {
    try {
      const { data, error } = await supabase
        .from('projects')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        console.warn('Error fetching projects:', error.message);
        return [];
      }
      return data || [];
    } catch (e) {
      console.error('Fetch Projects failed:', e);
      return [];
    }
  },

  saveProject: async (project: Partial<Project>) => {
    // Construct payload matching the DB schema (after running SQL)
    const payload = {
      title: project.title,
      description: project.description,
      department: project.department,
      status: project.status,
      visibility: project.visibility,
      trl: project.trl,
      research_area: project.research_area,
      image_url: project.image_url,
      budget: project.budget,
      start_date: project.start_date,

      // New columns
      funding_amount_usd: project.funding_amount_usd,
      open_to_collaboration: project.open_to_collaboration,
      technical_details_url: project.technical_details_url,
      achievements: project.achievements,
      needs: project.needs
    };

    if (project.id) {
      Object.assign(payload, { id: project.id });
    }

    const { data, error } = await supabase
      .from('projects')
      .upsert(payload)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  // News CRUD
  getNews: async (): Promise<NewsItem[]> => {
    try {
      const { data, error } = await supabase
        .from('news')
        .select('*')
        .order('published_at', { ascending: false });

      if (error) {
        return [];
      }
      return data || [];
    } catch (e) {
      return [];
    }
  },

  // EOIs
  submitEOI: async (project_id: string, user_name: string, message: string) => {
    const { error } = await supabase
      .from('eois')
      .insert([{
        project_id,
        user_name,
        message,
        read: false
      }]);

    if (error) throw error;
  },

  getEOIs: async () => {
    try {
      const { data, error } = await supabase
        .from('eois')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) return [];
      return data || [];
    } catch (e) {
      return [];
    }
  },

  // Profile Management
  getProfile: async (userId: string) => {
    if (!userId) return null;
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (error) return null;
      return data;
    } catch (e) {
      return null;
    }
  },

  updateProfile: async (profile: Partial<User>) => {
    const { error } = await supabase
      .from('profiles')
      .upsert(profile);

    if (error) throw error;
  }
};

