import { Project, NewsItem, User, UserRole } from '../types';
import { supabase } from '../lib/supabase';

export const StorageService = {
  // Initialization
  init: async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      return session;
    } catch (error) {
      console.error('Session initialization error:', error);
      return null;
    }
  },

  // --- FILE UPLOAD LOGIC ---
  uploadFile: async (file: File, bucket: string): Promise<string> => {
    // 1. Sanitize file name
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${fileExt}`;
    const filePath = `${fileName}`;

    // 2. Upload
    const { error: uploadError } = await supabase.storage
      .from(bucket)
      .upload(filePath, file);

    if (uploadError) {
      console.error(`Upload failed for bucket ${bucket}:`, uploadError);
      throw uploadError;
    }

    // 3. Get Public URL
    const { data } = supabase.storage.from(bucket).getPublicUrl(filePath);
    return data.publicUrl;
  },

  // Projects CRUD

  // Get ALL projects (for public viewing/partners)
  getProjects: async (): Promise<Project[]> => {
    try {
      const { data, error } = await supabase
        .from('projects')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) {
        console.warn('Error fetching projects:', error.message);
        return [];
      }
      return data || [];
    } catch (e) {
      console.error('Fetch Projects failed:', e);
      return [];
    }
  },

  // Get ONLY projects owned by a specific user (for Researcher Dashboard)
  getMyProjects: async (userId: string): Promise<Project[]> => {
    try {
      const { data, error } = await supabase
        .from('projects')
        .select('*')
        .eq('owner_id', userId)
        .order('created_at', { ascending: false });

      if (error) {
        return [];
      }
      return data || [];
    } catch (e) {
      return [];
    }
  },

  saveProject: async (project: Partial<Project>) => {
    // Get current user to set as owner
    const { data: { session } } = await supabase.auth.getSession();
    const ownerId = session?.user?.id;

    if (!ownerId && !project.id) throw new Error("User must be logged in to create a project");

    // Construct payload matching the DB schema
    const payload = {
      title: project.title,
      description: project.description,
      department: project.department,
      status: project.status,
      visibility: project.visibility,
      trl: project.trl,
      research_area: project.research_area,
      image_url: project.image_url,
      budget: project.budget,
      start_date: project.start_date,
      owner_id: ownerId, // Set ownership

      // New columns
      funding_amount_usd: project.funding_amount_usd,
      open_to_collaboration: project.open_to_collaboration,
      technical_details_url: project.technical_details_url,
      achievements: project.achievements,
      needs: project.needs
    };

    if (project.id) {
      Object.assign(payload, { id: project.id });
      // Don't overwrite owner_id on edit usually, but safe to keep consistent
    }

    const { data, error } = await supabase
      .from('projects')
      .upsert(payload)
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  // News CRUD
  getNews: async (): Promise<NewsItem[]> => {
    try {
      const { data, error } = await supabase
        .from('news')
        .select('*')
        .order('published_at', { ascending: false });

      if (error) {
        return [];
      }
      return data || [];
    } catch (e) {
      return [];
    }
  },

  // EOIs
  submitEOI: async (project_id: string, user_name: string, message: string) => {
    const { error } = await supabase
      .from('eois')
      .insert([{
        project_id,
        user_name,
        message,
        read: false
      }]);

    if (error) throw error;
  },

  getEOIs: async () => {
    try {
      const { data, error } = await supabase
        .from('eois')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) return [];
      return data || [];
    } catch (e) {
      return [];
    }
  },

  // Profile Management
  getProfile: async (userId: string) => {
    if (!userId) return null;
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (error) return null;
      return data;
    } catch (e) {
      return null;
    }
  },

  updateProfile: async (profile: Partial<User>) => {
    const { error } = await supabase
      .from('profiles')
      .upsert(profile);

    if (error) throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useNavigate, useLocation } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import AIAssistant from './components/AIAssistant';
import AuthModal from './components/AuthModal';
import Home from './pages/Home';
import Projects from './pages/Projects';
import ProjectDetail from './pages/ProjectDetail';
import Dashboards from './pages/Dashboards';
import Products from './pages/Products';
import News from './pages/News';
import Privacy from './pages/Privacy';
import Terms from './pages/Terms';
import { UserRole, User } from './types';
import { AlertCircle, X } from 'lucide-react';
import { supabase } from './lib/supabase';
import { StorageService } from './services/storageService';

// Protected Route Component
const ProtectedRoute: React.FC<{ 
  isAuthenticated: boolean; 
  children: React.ReactNode;
  onUnauthorized: () => void;
}> = ({ isAuthenticated, children, onUnauthorized }) => {
  const location = useLocation();

  useEffect(() => {
    if (!isAuthenticated && location.pathname === '/dashboard') {
      onUnauthorized();
    }
  }, [isAuthenticated, location.pathname, onUnauthorized]);

  if (!isAuthenticated) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

const AppContent: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userProfile, setUserProfile] = useState<User | null>(null);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [showLoginPrompt, setShowLoginPrompt] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    // Check active sessions and set up auth listener
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        setIsAuthenticated(true);
        loadProfile(session.user.id);
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        setIsAuthenticated(true);
        loadProfile(session.user.id);
      } else {
        setIsAuthenticated(false);
        setUserProfile(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const loadProfile = async (userId: string) => {
    const profile = await StorageService.getProfile(userId);
    if (profile) {
      setUserProfile(profile);
    } else {
      // Default fallback if profile record doesn't exist yet
      setUserProfile({ id: userId, email: '', name: 'Researcher', role: UserRole.Researcher });
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAuthenticated(false);
    setUserProfile(null);
    navigate('/');
  };

  const handleUserIconClick = () => {
    if (isAuthenticated) {
      navigate('/dashboard');
    } else {
      setIsAuthModalOpen(true);
    }
  };

  const handleUnauthorizedAccess = () => {
    setShowLoginPrompt(true);
    setIsAuthModalOpen(true);
  };

  return (
    <div className="flex flex-col min-h-screen font-sans text-gray-900">
      <Navbar 
          isAuthenticated={isAuthenticated}
          onUserIconClick={handleUserIconClick}
          onLogout={handleLogout}
      />

      {showLoginPrompt && !isAuthenticated && (
        <div className="bg-ug-warning/90 backdrop-blur-sm text-ug-navy py-3 px-4 flex items-center justify-center gap-3 animate-fade-in shadow-xl relative z-40 border-b border-ug-warning">
          <AlertCircle size={20} className="shrink-0" />
          <span className="text-xs sm:text-sm font-black uppercase tracking-widest">
            Identity Required: Please sign in to access secure researcher tools.
          </span>
          <button 
            onClick={() => setShowLoginPrompt(false)}
            className="ml-4 p-1 hover:bg-black/10 rounded-full transition"
          >
            <X size={16} />
          </button>
        </div>
      )}

      <main className="flex-grow">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/projects" element={<Projects />} />
          <Route path="/projects/:id" element={<ProjectDetail />} />
          <Route path="/products" element={<Products />} />
          <Route path="/news" element={<News />} />
          <Route path="/privacy" element={<Privacy />} />
          <Route path="/terms" element={<Terms />} />

          <Route 
              path="/dashboard" 
              element={
                <ProtectedRoute 
                  isAuthenticated={isAuthenticated} 
                  onUnauthorized={handleUnauthorizedAccess}
                >
                  <Dashboards 
                    role={userProfile?.role || UserRole.Researcher} 
                    user={userProfile} 
                  />
                </ProtectedRoute>
              } 
          />

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </main>

      <AuthModal 
          isOpen={isAuthModalOpen} 
          onClose={() => setIsAuthModalOpen(false)}
      />

      <AIAssistant />
      <Footer />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;

