          <div className="space-y-4">
            <h3 className="text-sm font-black text-ug-teal uppercase tracking-widest border-b border-gray-100 pb-2">3. Needs & Partnership</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-start">
               <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                  <label className="flex items-center gap-3 cursor-pointer">
                    <div className={`w-6 h-6 rounded flex items-center justify-center border transition ${openCollaboration ? 'bg-ug-teal border-ug-teal text-white' : 'bg-white border-gray-300'}`}>
                      {openCollaboration && <Check size={14} />}
                    </div>
                    <input type="checkbox" className="hidden" checked={openCollaboration} onChange={e => setOpenCollaboration(e.target.checked)} />
                    <div>
                       <span className="text-xs font-black text-ug-navy uppercase block">Open to Collaboration</span>
                    </div>
                  </label>
               </div>
               <div className="space-y-2">
                  <label className="text-xs font-black text-ug-navy uppercase tracking-widest flex items-center gap-1"><DollarSign size={14} /> Funding Needs (USD)</label>
                  <input type="number" placeholder="e.g. 50000" value={fundingAmount} onChange={e => setFundingAmount(e.target.value)} className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3 font-bold text-gray-700" />
               </div>
            </div>
          </div>

          <div className="space-y-4">
             <h3 className="text-sm font-black text-ug-teal uppercase tracking-widest border-b border-gray-100 pb-2">4. Attachments</h3>
             <div className="space-y-2">
                <label className="text-xs font-black text-ug-navy uppercase tracking-widest">Main Image (Required)</label>
                <input type="file" required accept="image/*" onChange={e => setMainImageFile(e.target.files?.[0] || null)} className="w-full text-xs text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-black file:bg-ug-navy/10 file:text-ug-navy hover:file:bg-ug-navy/20" />
             </div>
             <div className="bg-amber-50 p-4 rounded-xl border border-amber-100 space-y-2">
                <div className="flex items-center gap-2 mb-2">
                   <FileCode size={16} className="text-amber-600" />
                   <label className="text-xs font-black text-amber-800 uppercase tracking-widest">Technical Paper (Confidential)</label>
                </div>
                <input type="file" accept=".pdf" onChange={e => setTechDocFile(e.target.files?.[0] || null)} className="w-full text-xs text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-black file:bg-amber-200 file:text-amber-900 hover:file:bg-amber-300" />
             </div>
          </div>

          <div className="pt-4 border-t border-gray-100">
             <button disabled={loading} type="submit" className="w-full bg-ug-navy text-white py-4 rounded-xl font-black uppercase tracking-widest shadow-xl flex items-center justify-center gap-2 hover:bg-ug-teal transition-colors">
               {loading ? <Loader2 className="animate-spin" /> : 'Register Innovation'}
             </button>
          </div>
        </form>
      </div>
    </div>
  );
};

// --- RESEARCHER DASHBOARD (Unique per user) ---

const ResearcherDashboard = ({ user }: { user: User | null }) => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);
  const [eois, setEois] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  const loadData = async () => {
    if (!user?.id) return;
    setLoading(true);
    try {
      const pList = await StorageService.getMyProjects(user.id);
      const eList = await StorageService.getEOIs();
      setProjects(pList);
      setEois(eList);
    } catch (err) {
      console.error("Dashboard data load error:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, [user?.id]);

  const getThumbnail = (urlStr: string) => urlStr ? urlStr.split('|')[0] : '';

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
      <div className="lg:col-span-8 space-y-8">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <StatCard label="My Portfolio" value={projects.length} icon={Globe} color="bg-purple-50 text-purple-600" />
          <StatCard label="Inquiries" value={eois.length} sub="Real-time leads" icon={Users} color="bg-teal-50 text-ug-teal" />
        </div>

        <section className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <SectionTitle title="Live Disclosures" subtitle="Manage your research pipeline" />
            <button onClick={() => setIsProjectModalOpen(true)} className="flex items-center gap-2 bg-ug-navy text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-ug-teal transition shadow-xl hover:shadow-2xl">
              <Plus size={16} /> Add Disclosure
            </button>
          </div>
          <div className="space-y-4">
            {loading ? (
              <div className="flex justify-center py-10"><Loader2 className="animate-spin text-ug-teal" /></div>
            ) : projects.length === 0 ? (
               <div className="text-center py-16 bg-gray-50 rounded-3xl border border-dashed border-gray-200">
                  <p className="text-gray-400 font-bold uppercase text-xs tracking-widest">Welcome to the Hub!</p>
                  <p className="text-sm font-medium text-gray-500 mt-2">You haven't added any innovations yet.</p>
               </div>
            ) : projects.map(p => (
              <div key={p.id} onClick={() => navigate(`/projects/${p.id}`)} className="group flex items-center justify-between p-5 border border-gray-50 rounded-2xl bg-gray-50/30 hover:bg-white hover:border-ug-teal/30 hover:shadow-lg transition cursor-pointer">
                <div className="flex items-center gap-6">
                  <div className="w-16 h-16 rounded-xl overflow-hidden shadow-sm">
                     <img src={getThumbnail(p.image_url)} className="w-full h-full object-cover" alt="" />
                  </div>
                  <div>
                     <h4 className="font-black text-ug-navy text-lg group-hover:text-ug-teal transition-colors">{p.title}</h4>
                     <div className="flex items-center gap-3 mt-1">
                        <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">{p.research_area}</span>
                        <span className="text-[10px] font-bold bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full uppercase">TRL {p.trl}</span>
                     </div>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <div className="text-right hidden sm:block">
                     <p className="text-[10px] font-bold text-gray-400 uppercase">Status</p>
                     <p className="text-xs font-bold text-ug-navy">{p.status}</p>
                  </div>
                  <ChevronRight size={18} className="text-gray-300 group-hover:text-ug-teal" />
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>

      <div className="lg:col-span-4 space-y-8">
        <section className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm h-full">
          <h3 className="font-black text-ug-navy text-lg mb-8 flex items-center gap-3">
             <div className="p-2 bg-ug-teal/10 rounded-lg text-ug-teal"><Bell size={20} /></div> Hub Stream
          </h3>
          <div className="space-y-4">
            {eois.length === 0 ? <p className="text-sm text-gray-400 italic">No new notifications.</p> : eois.map((e, i) => (
              <div key={i} className="text-sm p-5 bg-gray-50 rounded-2xl text-gray-600 border border-gray-100 relative overflow-hidden group hover:border-ug-teal/30 transition">
                <div className="absolute left-0 top-0 bottom-0 w-1 bg-ug-teal"></div>
                <p className="text-ug-teal text-[10px] font-black uppercase tracking-widest mb-2">Partnership Interest</p>
                <p className="font-bold text-ug-navy mb-1">{e.user_name}</p>
                <p className="text-xs leading-relaxed">{e.message.substring(0, 80)}...</p>
              </div>
            ))}
          </div>
        </section>
      </div>
      <ProjectFormModal isOpen={isProjectModalOpen} onClose={() => setIsProjectModalOpen(false)} onSave={loadData} />
    </div>
  );
};

