             <div>
                <h1 className="text-5xl font-black text-ug-navy tracking-tight">{role} Portal</h1>
                {user && (
                   <div className="flex items-center gap-2 mt-2">
                      <span className="h-0.5 w-6 bg-ug-teal"></span>
                      <p className="text-lg font-bold text-ug-teal uppercase tracking-widest">
                        Welcome, <span className="text-ug-navy">{user.name}</span>
